  "fulfillment" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "assignment") REFERENCES assignment ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment") REFERENCES fulfillment ("tenant", "id")
);

CREATE TABLE assignment_offer_end (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "offer" TEXT COLLATE "C" NOT NULL,
  "outcome" TEXT COLLATE "C" NOT NULL,
  "at" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "offer") REFERENCES assignment_offer ("tenant", "id")
);

CREATE TABLE settlement_source (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "book" TEXT COLLATE "C" NOT NULL,
  "key_" TEXT COLLATE "C" NOT NULL,
  "kind" TEXT COLLATE "C" NOT NULL,
  "unit" TEXT COLLATE "C" NOT NULL,
  "quantity" BIGINT NOT NULL,
  "occurred_at" TEXT COLLATE "C" NOT NULL,
  "fulfillment_end" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "book") REFERENCES settlement_book ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment_end") REFERENCES fulfillment_end ("tenant", "id")
);

CREATE TABLE settlement_commit (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "book" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "previous" TEXT COLLATE "C",
  "event" TEXT COLLATE "C" NOT NULL,
  "source" TEXT COLLATE "C",
  "key_" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "book") REFERENCES settlement_book ("tenant", "id"),
  FOREIGN KEY ("tenant", "previous") REFERENCES settlement_commit ("tenant", "id"),
  FOREIGN KEY ("tenant", "source") REFERENCES settlement_source ("tenant", "id")
);

CREATE TABLE settlement_event (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "book" TEXT COLLATE "C" NOT NULL,
  "key_" TEXT COLLATE "C" NOT NULL,
  "kind" TEXT COLLATE "C" NOT NULL,
  "head" TEXT COLLATE "C" NOT NULL,
  "source" TEXT COLLATE "C",
  "occurred_at" TEXT COLLATE "C" NOT NULL,
  "effective_at" TEXT COLLATE "C" NOT NULL,
  "reversal_of" TEXT COLLATE "C",
  "reason" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "book") REFERENCES settlement_book ("tenant", "id"),
  FOREIGN KEY ("tenant", "head") REFERENCES settlement_line ("tenant", "id"),
  FOREIGN KEY ("tenant", "source") REFERENCES settlement_source ("tenant", "id"),
  FOREIGN KEY ("tenant", "reversal_of") REFERENCES settlement_commit ("tenant", "id")
);

CREATE TABLE settlement_ledger_link (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "publication" TEXT COLLATE "C" NOT NULL,
  "posting" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "publication") REFERENCES settlement_commit ("tenant", "id"),
  FOREIGN KEY ("tenant", "posting") REFERENCES posting_group ("tenant", "id")
);

